#![allow(clippy::double_must_use)] // Async methods generated by `rpc` add `must_use`.

use alloy::{
    primitives::{Address, B256, U256},
    providers::{DynProvider, Provider},
    sol_types::SolCall,
};
use async_trait::async_trait;
use jsonrpsee::{core::RpcResult, proc_macros::rpc, types::error::INTERNAL_ERROR_CODE};
use reth_rpc_server_types::result::rpc_err;
use tempo_alloy::{TempoNetwork, primitives::transaction::Call, rpc::TempoTransactionRequest};
use tempo_precompiles::tip20::ITIP20;

#[rpc(server, namespace = "tempo")]
pub trait TempoFaucetExtApi {
    #[method(name = "fundAddress")]
    async fn fund_address(&self, address: Address) -> RpcResult<Vec<B256>>;
}

pub struct TempoFaucetExt {
    faucet_token_addresses: Vec<Address>,
    funding_amount: U256,
    provider: DynProvider<TempoNetwork>,
}

impl TempoFaucetExt {
    pub fn new(
        faucet_token_addresses: Vec<Address>,
        funding_amount: U256,
        provider: DynProvider<TempoNetwork>,
    ) -> Self {
        Self {
            faucet_token_addresses,
            funding_amount,
            provider,
        }
    }
}

#[async_trait]
impl TempoFaucetExtApiServer for TempoFaucetExt {
    async fn fund_address(&self, address: Address) -> RpcResult<Vec<B256>> {
        // Batch mints so each request holds few of the faucet signer's 16 pool slots, within
        // the txpool's 32 calls per transaction.
        let mut tx_hashes = Vec::new();
        for tokens in self.faucet_token_addresses.chunks(32) {
            let calls = tokens
                .iter()
                .map(|token| Call {
                    to: (*token).into(),
                    value: U256::ZERO,
                    input: ITIP20::mintCall {
                        to: address,
                        amount: self.funding_amount,
                    }
                    .abi_encode()
                    .into(),
                })
                .collect();
            let tx_hash = *self
                .provider
                .send_transaction(TempoTransactionRequest::default().with_calls(calls))
                .await
                .map_err(|err| rpc_err(INTERNAL_ERROR_CODE, err.to_string(), None))?
                .tx_hash();
            tx_hashes.push(tx_hash);
        }

        Ok(tx_hashes)
    }
}
